<template><section><div class="page-head"><div><span class="eyebrow">Your library</span><h1 class="page-title">Images</h1><p class="muted">Select pictures from this device to view them here.</p></div><button class="button" @click="$emit('action',{action:'file-select'})">Add pictures</button></div><div v-if="state.files.filter(f=>f.type.startsWith('image/')).length" class="file-grid"><button v-for="file in state.files.filter(f=>f.type.startsWith('image/'))" :key="file.url" class="file-card" @click="state.mediaUrl=file.url"><img :src="file.url" :alt="file.name"><small>{{file.name}}</small></button></div><div v-else class="empty">No pictures added yet.<br><button class="quiet" @click="$emit('action',{action:'folder-select'})">Add Folder</button></div><div v-if="state.mediaUrl" class="overlay" @click.self="state.mediaUrl=''"><img :src="state.mediaUrl" alt="Image viewer" style="max-width:95vw;max-height:90vh;border-radius:14px"><button class="icon-button" @click="state.mediaUrl=''">Close ✕</button></div></section></template>
